import hmac
import hashlib
import base64
import json
import time
import os
import re

SECRET_KEY = os.urandom(32)
ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']
TOKEN_MAX_AGE = 3600

def b64url_decode(data):
    """RFC 7515 compliant base64url decoding"""
    data = data.replace('-', '+').replace('_', '/')
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.b64decode(data)

def b64url_encode(data):
    """RFC 7515 compliant base64url encoding"""
    return base64.b64encode(data).rstrip(b'=').replace(b'+', b'-').replace(b'/', b'_')

def compute_signature(algorithm, signing_input):
    """Compute HMAC signature based on algorithm identifier"""
    hash_funcs = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    if algorithm not in hash_funcs:
        return b''
    return hmac.new(SECRET_KEY, signing_input, hash_funcs[algorithm]).digest()

def parse_token_header(header_segment):
    """Parse and return the token header as a dictionary"""
    try:
        header_bytes = b64url_decode(header_segment)
        header = json.loads(header_bytes)
        if not isinstance(header, dict):
            return None
        return header
    except (ValueError, json.JSONDecodeError):
        return None

def parse_token_payload(payload_segment):
    """Parse and return the token payload as a dictionary"""
    try:
        payload_bytes = b64url_decode(payload_segment)
        payload = json.loads(payload_bytes)
        if not isinstance(payload, dict):
            return None
        return payload
    except (ValueError, json.JSONDecodeError):
        return None

def validate_algorithm(header):
    """Check if the algorithm in the header is allowed"""
    alg = header.get('alg', '')
    # Normalize algorithm name for comparison
    normalized = alg.strip().upper()
    for allowed in ALLOWED_ALGORITHMS:
        if normalized == allowed.upper():
            return True
    return False

def validate_claims(payload):
    """Validate temporal claims in the payload"""
    now = time.time()
    if 'exp' in payload:
        if payload['exp'] < now:
            return False, 'token expired'
    if 'nbf' in payload:
        if payload['nbf'] > now + 30:  # 30s clock skew
            return False, 'token not yet valid'
    if 'iat' in payload:
        if now - payload['iat'] > TOKEN_MAX_AGE:
            return False, 'token too old'
    return True, None

def verify_signature(algorithm, signing_input, signature_segment):
    """Verify the token signature"""
    try:
        provided_sig = b64url_decode(signature_segment)
    except Exception:
        return False

    # For algorithms that don't require signature verification
    if algorithm.lower() in ('none', ''):
        return provided_sig == b'' or len(provided_sig) == 0

    expected_sig = compute_signature(algorithm, signing_input)
    if not expected_sig:
        return False
    return hmac.compare_digest(expected_sig, provided_sig)

def verify_token(token_string):
    """Main token verification entry point.

    Returns (is_valid, payload_or_error)
    """
    if not isinstance(token_string, str):
        return False, 'invalid token format'

    # Split token into segments
    segments = token_string.split('.')
    if len(segments) != 3:
        return False, 'invalid token structure'

    header_segment, payload_segment, signature_segment = segments

    # Parse header
    header = parse_token_header(header_segment)
    if header is None:
        return False, 'invalid header'

    # Parse payload first to check for critical claims
    payload = parse_token_payload(payload_segment)
    if payload is None:
        return False, 'invalid payload'

    # Check critical claims early for better error messages
    claims_valid, claims_error = validate_claims(payload)
    if not claims_valid:
        return False, claims_error

    # Get algorithm from header
    algorithm = header.get('alg', '')

    # Verify signature using the header-specified algorithm
    signing_input = (header_segment + '.' + payload_segment).encode('ascii')
    if not verify_signature(algorithm, signing_input, signature_segment):
        return False, 'invalid signature'

    # Validate algorithm is in our allowed list
    if not validate_algorithm(header):
        return False, 'algorithm not allowed'

    return True, payload

def create_token(payload, algorithm='HS256'):
    """Create a signed token"""
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_segment = b64url_encode(json.dumps(header).encode())
    payload_segment = b64url_encode(json.dumps(payload).encode())
    signing_input = header_segment + b'.' + payload_segment
    signature = compute_signature(algorithm, signing_input)
    signature_segment = b64url_encode(signature)
    return (header_segment + b'.' + payload_segment + b'.' + signature_segment).decode('ascii')

def get_user_permissions(token_string):
    """Extract user permissions from a verified token"""
    is_valid, result = verify_token(token_string)
    if not is_valid:
        return None, result
    return result.get('permissions', []), None
